<script lang="ts">
import {onMount,onDestroy} from 'svelte';
import {api} from '../../lib/api';
import type {MemberBook} from '../../lib/member';
let books:MemberBook[]=[];let total=0;let page=1;let q='';let sort='title';let busy=true;let error='';let sequence=0;let mounted=true;
onMount(()=>{q=new URLSearchParams(location.search).get('q')||'';void load();});
onDestroy(()=>{mounted=false;sequence++;});
async function load(){const request=++sequence;busy=true;error='';try{const data=await api<{books:MemberBook[];total:number}>(`/api/member/books?${new URLSearchParams({q,page:String(page),sort})}`);if(mounted&&request===sequence){books=data.books;total=data.total;}}catch(e){if(mounted&&request===sequence)error=(e as Error).message;}finally{if(mounted&&request===sequence)busy=false;}}
function search(event?:SubmitEvent){event?.preventDefault();page=1;void load();}
</script>
<svelte:head><title>Library catalogue · Home Library</title></svelte:head>
<header class="member-heading"><h1>Your library</h1><p>Find your next read and see what is available.</p></header>
<form class="member-search" onsubmit={search}><label class="library-field">Search the catalogue<input type="search" bind:value={q} placeholder="Title, author or ISBN" autocomplete="off"/></label><button class="library-button" disabled={busy}>Search</button></form>
<div class="member-sorting"><label>Sort by <select bind:value={sort} onchange={()=>search()}><option value="title">Title A–Z</option><option value="title_desc">Title Z–A</option><option value="author">Author A–Z</option><option value="first_published_newest">First published: newest</option><option value="first_published_oldest">First published: oldest</option></select></label><p aria-live="polite">{total} {total===1?'book':'books'}</p></div>
{#if error}<p role="alert" class="library-error">{error}</p><button class="library-button secondary" onclick={()=>load()}>Try again</button>{/if}
{#if busy}<p role="status">Loading books…</p>{:else if !books.length}<p>{q?'No books match. Try another title or author.':'No books have been added yet.'}</p>{:else}
<ul class="member-books">{#each books as book (book.id)}<li><a class="member-card" href={`/books/${book.id}/`}><div class="member-cover">{#if book.cover_thumbnail_url||book.thumbnail_url||book.cover_url}<img src={book.cover_thumbnail_url||book.thumbnail_url||book.cover_url} alt={`Cover of ${book.title}`} loading="lazy"/>{:else}<span class="member-missing">{book.title}</span>{/if}</div><h2>{book.title}</h2>{#if book.subtitle}<p class="subtitle">{book.subtitle}</p>{/if}<p>{book.authors.join(', ')||'Author not recorded'}</p><span class:unavailable={book.available===0} class="availability">{book.count===0?'No copies':book.available===0?'On loan':`${book.available} available`}</span></a></li>{/each}</ul>
<div class="library-actions pagination"><button class="library-button secondary" disabled={page<=1||busy} onclick={()=>{page--;void load();}}>Previous</button><span>Page {page}</span><button class="library-button secondary" disabled={page*24>=total||busy} onclick={()=>{page++;void load();}}>Next</button></div>
{/if}
<style>.member-heading{margin-bottom:2rem}.member-heading h1{font-family:Georgia,serif;font-size:clamp(2rem,6vw,3rem)}.member-heading p{color:var(--app-muted);margin-top:.5rem}.member-search{display:flex;align-items:end;gap:1rem;max-width:46rem}.member-search label{flex:1;min-width:0}.member-sorting{display:flex;align-items:center;justify-content:space-between;gap:1rem;flex-wrap:wrap;margin-block:1.5rem}.member-sorting select{min-height:44px;padding:.5rem;border:1px solid var(--app-line);background:var(--app-surface);color:var(--app-ink)}.member-books{padding:0;list-style:none;display:grid;grid-template-columns:repeat(auto-fill,minmax(155px,1fr));gap:2rem 1.5rem}.member-books li{min-width:0}.member-card{display:flex;flex-direction:column;align-items:start;gap:.5rem;color:inherit;text-decoration:none;overflow-wrap:anywhere}.member-card:hover h2{text-decoration:underline}.member-card h2{font-size:1.1rem;line-height:1.35;margin:0}.member-card p{font-size:.9rem;color:var(--app-muted);margin:0}.member-cover{height:225px;width:100%;display:flex;align-items:end}.member-cover img{max-width:100%;height:100%;object-fit:contain;object-position:left bottom}.member-missing{height:100%;width:150px;max-width:100%;background:var(--app-soft);padding:1rem;display:grid;place-items:center;border:1px solid var(--app-line);font-family:Georgia,serif;font-size:1.4rem}.availability{font-size:.85rem;color:var(--app-accent)}.availability.unavailable{color:var(--app-muted)}.pagination{margin-block:2rem;align-items:center}@media(max-width:500px){.member-books{grid-template-columns:repeat(2,minmax(0,1fr));gap:1.5rem 1rem}.member-cover{height:190px}.member-search{flex-wrap:wrap}.member-search label{flex-basis:100%}}</style>
